datasource db {
  provider = "sqlite"
  // Wasp requires that the url is set to the DATABASE_URL environment variable.
  url      = env("DATABASE_URL")
}

// Wasp requires the `prisma-client-js` generator to be present.
generator client {
  provider = "prisma-client-js"
}

model Project {
  id    Int    @id @default(autoincrement())
  name  String
  tasks Task[]
}

model Task {
  id        Int     @id @default(autoincrement())
  title     String
  done      Boolean @default(false)
  project   Project @relation(fields: [projectId], references: [id])
  projectId Int
}

app taskboard {
  wasp: {
    version: "^0.16.7"
  },
  title: "taskboard",
  db: {
    seeds: [
      import { devSeed } from "@src/server/dbSeed.js"
    ]
  }
}

route RootRoute { path: "/", to: MainPage }
page MainPage {
  component: import { MainPage } from "@src/MainPage"
}

query getTasks {
  fn: import { getTasks } from "@src/server/queries.js",
  entities: [Task]
}

query getProjectStats {
  fn: import { getProjectStats } from "@src/server/queries.js",
  entities: [Project]
}

action addTask {
  fn: import { addTask } from "@src/server/actions.js",
  entities: [Task]
}

action toggleTask {
  fn: import { toggleTask } from "@src/server/actions.js",
  entities: [Task]
}

/**
 * Returns every task with its id, title, done state and project id.
 *
 * Wasp automatically invalidates any query that declares the same entities as
 * an Action. We list `Task` so Wasp will keep `getTasks` in sync whenever
 * `addTask` or `toggleTask` runs.
 */
export const getTasks = async (_args, context) => {
  return context.entities.Task.findMany({
    select: {
      id: true,
      title: true,
      done: true,
      projectId: true,
    },
    orderBy: { id: 'asc' },
  });
};

/**
 * Returns, for every project, the project's id, its name, the total number of
 * tasks in that project, and the number of done tasks.
 *
 * NOTE: We intentionally only declare `Project` as the entity in `main.wasp`.
 * That means adding or toggling a task will NOT automatically invalidate this
 * query -- the client must keep it fresh manually using react-query.
 */
export const getProjectStats = async (_args, context) => {
  const projects = await context.entities.Project.findMany({
    select: {
      id: true,
      name: true,
      tasks: {
        select: {
          done: true,
        },
      },
    },
    orderBy: { id: 'asc' },
  });

  return projects.map((project) => ({
    id: project.id,
    name: project.name,
    total: project.tasks.length,
    done: project.tasks.filter((t) => t.done).length,
  }));
};

/**
 * Creates a new task in the given project.
 *
 * Both this Action and `toggleTask` declare `Task` as an entity, so Wasp will
 * automatically invalidate any Query that also reads `Task` (notably
 * `getTasks`). The derived `getProjectStats` Query deliberately does NOT
 * declare `Task`, so the client has to keep it fresh itself.
 */
export const addTask = async ({ projectId, title }, context) => {
  return context.entities.Task.create({
    data: {
      title,
      done: false,
      project: {
        connect: { id: projectId },
      },
    },
  });
};

/**
 * Flips a task's done state.
 */
export const toggleTask = async ({ taskId }, context) => {
  const task = await context.entities.Task.findUnique({
    where: { id: taskId },
    select: { id: true, done: true },
  });

  if (!task) {
    throw new Error(`Task with id ${taskId} not found`);
  }

  return context.entities.Task.update({
    where: { id: taskId },
    data: { done: !task.done },
  });
};

/**
 * `devSeed` -- the only Wasp db seed for this app.
 *
 * It is safe to run repeatedly and always leaves the database in exactly this
 * deterministic state:
 *   - project "Work":  tasks "Ship release" (done) and "Write docs" (not done)
 *   - project "Home":  task  "Buy groceries"   (not done)
 *
 * Invoke with: `wasp db seed devSeed`.
 */
export const devSeed = async (prismaClient) => {
  // Clear any prior projects/tasks so the result is deterministic.
  await prismaClient.task.deleteMany({});
  await prismaClient.project.deleteMany({});

  await prismaClient.project.create({
    data: {
      name: 'Work',
      tasks: {
        create: [
          { title: 'Ship release', done: true },
          { title: 'Write docs', done: false },
        ],
      },
    },
  });

  await prismaClient.project.create({
    data: {
      name: 'Home',
      tasks: {
        create: [{ title: 'Buy groceries', done: false }],
      },
    },
  });
};

import { useQuery, useQueryClient } from '@tanstack/react-query'
import {
  getTasks,
  getProjectStats,
  addTask,
  toggleTask,
} from 'wasp/client/operations'
import './Main.css'

/**
 * The page mounted at `/`.
 *
 * It reads two Queries and invokes two Actions:
 *  - `getTasks`    : Wasp keeps this fresh automatically because the Actions
 *                    share its `Task` entity.
 *  - `getProjectStats` : deliberately only declares `Project`, so Wasp does
 *                    NOT auto-invalidate it. We invalidate it ourselves using
 *                    the React Query `QueryClient` (react-query is bundled
 *                    with Wasp and importable from `@tanstack/react-query`).
 *                    A Wasp client Query exposes its cache key via
 *                    `query.queryCacheKey`, which we pass straight into
 *                    `queryClient.invalidateQueries(...)`.
 */
export const MainPage = () => {
  const { data: tasks, isLoading: tasksLoading } = useQuery(getTasks)
  const { data: projectStats, isLoading: statsLoading } = useQuery(getProjectStats)
  const queryClient = useQueryClient()

  const handleAddTask = async (projectId) => {
    const title = `New task ${Date.now()}`
    await addTask({ projectId, title })
    // `getProjectStats` does NOT auto-invalidate, so we do it ourselves.
    queryClient.invalidateQueries(getProjectStats.queryCacheKey)
  }

  const handleToggleTask = async (taskId) => {
    await toggleTask({ taskId })
    queryClient.invalidateQueries(getProjectStats.queryCacheKey)
  }

  if (tasksLoading || statsLoading) {
    return <div className="container">Loading...</div>
  }

  return (
    <div className="container">
      <main>
        <h1 className="welcome-title">Task Board</h1>

        <section>
          <h2>Projects</h2>
          {projectStats && projectStats.map((project) => (
            <div key={project.id} className="project">
              <h3>{project.name}</h3>
              <div>
                Total:{' '}
                <span data-testid={`stat-total-${project.id}`}>{project.total}</span>
              </div>
              <div>
                Done:{' '}
                <span data-testid={`stat-done-${project.id}`}>{project.done}</span>
              </div>
              <button
                data-testid={`add-task-${project.id}`}
                onClick={() => handleAddTask(project.id)}
              >
                Add task
              </button>
            </div>
          ))}
        </section>

        <section>
          <h2>Tasks</h2>
          <ul>
            {tasks && tasks.map((task) => (
              <li key={task.id} data-testid={`task-${task.id}`}>
                <span style={{ marginRight: '0.5rem' }}>
                  {task.title} {task.done ? '(done)' : ''}
                </span>
                <button
                  data-testid={`toggle-${task.id}`}
                  onClick={() => handleToggleTask(task.id)}
                >
                  Toggle
                </button>
              </li>
            ))}
          </ul>
        </section>
      </main>
    </div>
  )
}

